                <ListItemIcon>
                  <SummarizeIcon color={showSummaryPanel ? "primary" : "inherit"} />
                </ListItemIcon>
                <ListItemText primary="Smart Summary" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem>
                <Typography variant="body2" color="text.secondary">
                  SUBSCRIPTIONS
                </Typography>
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>M</Avatar>
                </ListItemIcon>
                <ListItemText primary="Music" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>S</Avatar>
                </ListItemIcon>
                <ListItemText primary="Sports" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>G</Avatar>
                </ListItemIcon>
                <ListItemText primary="Gaming" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon sx={{ minWidth: 32 }}>
                  <Avatar sx={{ width: 24, height: 24 }}>N</Avatar>
                </ListItemIcon>
                <ListItemText primary="News" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem>
                <Typography variant="body2" color="text.secondary">
                  EXPLORE
                </Typography>
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <MusicNoteIcon />
                </ListItemIcon>
                <ListItemText primary="Music" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <MovieIcon />
                </ListItemIcon>
                <ListItemText primary="Movies & TV" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <SportsEsportsIcon />
                </ListItemIcon>
                <ListItemText primary="Gaming" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <NewspaperIcon />
                </ListItemIcon>
                <ListItemText primary="News" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem button disabled>
                <ListItemIcon>
                  <SettingsIcon />
                </ListItemIcon>
                <ListItemText primary="Settings" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
                  <HelpOutlineIcon />
                </ListItemIcon>
                <ListItemText primary="Help" />
              </ListItem>
              <ListItem button disabled>
                <ListItemIcon>
